<?php
require __DIR__.'/app/bootstrap.php';
require_once __DIR__.'/app/Services/TripSpendExecutionService.php';

$userId=require_auth();$tripId=(int)($_GET['id']??$_POST['trip_id']??0);if($tripId<1){http_response_code(400);exit('Trip is required.');}
$service=new TripSpendExecutionService(db());$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        if(!$service->ready())throw new RuntimeException('Run System Upgrade through migration 061 for Live Trip Spend + Budget Execution.');
        $action=(string)($_POST['action']??'');
        if($action==='capture_expense'){$service->captureExpense($userId,$tripId,$_POST);flash('success','Actual spend captured in the private trip ledger.');}
        elseif($action==='save_settings'){$service->saveSettings($userId,$tripId,$_POST);flash('success','Live-spend pacing settings updated.');}
        elseif($action==='update_meta'){$service->updateEntryMeta($userId,$tripId,(int)($_POST['entry_id']??0),$_POST);flash('success','Receipt, reconciliation and attribution details updated.');}
        elseif($action==='void_expense'){$service->voidExpense($userId,$tripId,(int)($_POST['entry_id']??0),(string)($_POST['void_reason']??''));flash('success','Expense correction recorded without deleting the audit trail.');}
        else throw new InvalidArgumentException('Unknown live-spend action.');
        redirect('trip-spend.php?id='.$tripId);
    }catch(InvalidArgumentException|DomainException|OutOfBoundsException $e){$error=$e->getMessage();}
    catch(Throwable $e){error_log('Live Trip Spend update failed: '.$e->getMessage());$error='Vacation Brain could not update live trip spend safely. Check the server log or try again.';}
}
try{$snapshot=$service->snapshot($userId,$tripId);}catch(OutOfBoundsException $e){http_response_code(404);exit('Trip not found.');}
$trip=$snapshot['trip'];$owner=!empty($snapshot['can_manage']);$execution=$snapshot['execution']??[];$settings=$snapshot['settings']??[];$success=flash('success');$title='Live Trip Spend — '.$trip['name'];$pageStyles=['assets/trip-spend.css'];
function vb_spend_money(mixed $v,string $c):string{return $v===null||$v===''?'—':($c==='USD'?'$':$c.' ').number_format((float)$v,2);}
function vb_spend_label(string $v):string{return ucwords(str_replace('_',' ',$v));}
$currency=(string)($execution['currency']??$trip['currency']??'USD');
require __DIR__.'/partials/header.php';
?>
