<header class="vb-spend-head"><div><a class="back-link" href="<?=e(app_url('dream-trip.php?id='.$tripId.'&workspace=spend'))?>">← Trip workspace</a><span class="eyebrow">Live Trip Spend · Budget Execution</span><h1>Stay on budget while the trip is actually happening.</h1><p>Track owner-entered actual spend, reconcile receipts and bookings, watch daily pace, and get non-destructive ways to recover before a small overage becomes the trip budget.</p></div><div class="vb-spend-actions"><a class="button secondary" href="<?=e(app_url('trip-cost.php?id='.$tripId))?>">True Trip Economics</a><a class="button secondary" href="<?=e(app_url('trip-affordability.php?id='.$tripId))?>">Affordability</a><?php if(($trip['operational_state']??'')==='traveling'):?><a class="button primary" href="<?=e(app_url('travel-mode.php?id='.$tripId))?>">Travel Mode</a><?php endif;?></div></header>
<?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<?php if(!$snapshot['ready']):?><div class="alert error"><strong>Live Trip Spend needs migration 061 / app v1.53.</strong> <?php if(is_admin()):?><a href="<?=e(app_url('upgrade.php'))?>">Run System Upgrade</a><?php endif;?></div><?php endif;?>
