<?php else:?>
<section class="vb-spend-scoreboard">
<article><span>Recorded actual</span><strong><?=e(vb_spend_money($execution['actual_spend']??0,$currency))?></strong><small>Owner-entered, non-void ledger</small></article>
<article><span>Target budget</span><strong><?=e(vb_spend_money($execution['target_budget']??null,$currency))?></strong><small><?=($execution['spend_pct']??null)!==null?e(number_format((float)$execution['spend_pct'],1)).'% used':'Set a target budget to activate pacing'?></small></article>
<article class="pace-<?=e((string)($execution['pace_status']??'unknown'))?>"><span>Budget pace</span><strong><?=e(vb_spend_label((string)($execution['pace_status']??'unknown')))?></strong><small><?=($execution['remaining_budget']??null)!==null?e(vb_spend_money($execution['remaining_budget'],$currency)).' remaining':'Target required'?></small></article>
<article><span>Daily allowance left</span><strong><?=e(vb_spend_money($execution['remaining_daily_allowance']??null,$currency))?></strong><small><?=(int)($execution['days_remaining']??0)?> trip day<?=((int)($execution['days_remaining']??0)===1?'':'s')?> remaining</small></article>
<article><span>Planning expected final</span><strong><?=e(vb_spend_money($execution['planning_expected_final']??null,$currency))?></strong><small>Forecast, not settled spend</small></article>
