<label>Category<select name="cost_category"><?php foreach($snapshot['categories'] as $key=>$label):?><option value="<?=e($key)?>"><?=e($label)?></option><?php endforeach;?></select></label><label>Amount<input required name="amount" inputmode="decimal" placeholder="0.00"></label><label>Currency<input readonly name="currency" maxlength="3" value="<?=e($currency)?>"></label><label>Date / time<input type="datetime-local" name="occurred_at"></label><label>Merchant / provider<input name="merchant_name" maxlength="180" placeholder="Owner only"></label><label>Private note<input name="note" maxlength="1200" placeholder="Excluded from agent context"></label>
