<section class="vb-spend-card"><span class="eyebrow">Private spend ledger</span><h2>Receipts, reconciliation and corrections.</h2><div class="vb-spend-ledger"><?php if(empty($snapshot['entries'])):?><p>No actual expenses recorded yet.</p><?php endif;?><?php foreach($snapshot['entries'] as $entry):?><article class="vb-spend-entry <?=!empty($entry['voided_at'])?'is-void':''?>"><div class="vb-spend-entry-head"><div><strong><?=e($snapshot['categories'][$entry['cost_category']]??vb_spend_label((string)$entry['cost_category']))?> · <?=e(vb_spend_money($entry['amount'],(string)$entry['currency']))?></strong><small><?=e((string)($entry['merchant_name']?:'Merchant not recorded'))?><?php if($entry['occurred_at']):?> · <?=e(date('M j, Y g:i A',strtotime((string)$entry['occurred_at'])))?><?php endif;?></small></div><span><?=!empty($entry['voided_at'])?'Voided':e(vb_spend_label((string)$entry['reconciliation_status']))?></span></div><?php if($entry['note']):?><p><?=e((string)$entry['note'])?></p><?php endif;?><?php if($entry['receipt_reference']):?><small>Receipt reference: <?=e((string)$entry['receipt_reference'])?></small><?php endif;?>
