 value="<?=$tripId?>"><input type="hidden" name="action" value="void_expense"><input type="hidden" name="entry_id" value="<?=(int)$entry['id']?>"><input required name="void_reason" maxlength="500" placeholder="Reason for correction"><button class="button secondary small" type="submit">Void entry</button></form><?php else:?><small>Correction: <?=e((string)$entry['void_reason'])?></small><?php endif;?></article><?php endforeach;?></div></section>
